<body>
  <a class="skip-link" href="#maincontent">Skip to main content</a>
  <div id="root"></div>

  <script>
    const state = {
      values: {
        fullName: "",
        email: "",
        phone: ""
      },
      touched: {
        fullName: false,
        email: false,
        phone: false
      },
      errors: {},
      submitError: "",
      statusMessage: ""
    };

    const FIELD_ORDER = ["fullName", "email", "phone"];

    function escapeHtml(value) {
      return value
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");
    }

    function getFieldConfig(name) {
      const configs = {
        fullName: {
          id: "full-name",
          label: "Full name",
          type: "text",
          autocomplete: "name",
          inputMode: "text",
          required: true
        },
        email: {
          id: "email-address",
          label: "Email address",
          type: "email",
          autocomplete: "email",
          inputMode: "email",
          required: true
        },
        phone: {
          id: "phone-number",
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          inputMode: "tel",
          required: false,
          helperText: "Expected format: +1 555 123 4567 or (555) 123-4567."
        }
      };

      return configs[name];
    }

    function validateField(name, value) {
      const trimmedValue = value.trim();

      if (name === "fullName") {
        if (!trimmedValue) {
          return "Error: Enter your full name.";
        }
      }

      if (name === "email") {
        if (!trimmedValue) {
          return "Error: Enter your email address.";
        }

        const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        if (!emailPattern.test(trimmedValue)) {
          return "Error: Enter a valid email address, like name@example.com.";
        }
      }

      if (name === "phone" && trimmedValue) {
        const phonePattern = /^\+?[0-9()\-\s.]{7,20}$/;
        const digitsOnly = trimmedValue.replace(/\D/g, "");
        if (!phonePattern.test(trimmedValue) || digitsOnly.length < 7) {
          return "Error: Enter a valid phone number in the expected format.";
        }
      }

      return "";
    }

    function validateAll(values) {
      return FIELD_ORDER.reduce((errors, fieldName) => {
        const error = validateField(fieldName, values[fieldName]);
        if (error) {
          errors[fieldName] = error;
        }
        return errors;
      }, {});
    }

    function FormField(name) {
      const config = getFieldConfig(name);
      const error = state.errors[name];
      const helperId = config.helperText ? config.id + "-helper" : "";
      const errorId = config.id + "-error";
      const describedBy = [config.helperText ? helperId : "", error ? errorId : ""]
        .filter(Boolean)
        .join(" ");

      return `
        <div class="form-field">
          <label for="${config.id}">
            ${config.label}${config.required ? ' <span class="required-mark" aria-hidden="true">*</span>' : ' <span aria-hidden="true">(optional)</span>'}
          </label>
          <input
            id="${config.id}"
            name="${name}"
            type="${config.type}"
            value="${escapeHtml(state.values[name])}"
            autocomplete="${config.autocomplete}"
            inputmode="${config.inputMode}"
            ${config.required ? "required" : ""}
            ${describedBy ? `aria-describedby="${describedBy}"` : ""}
            ${error ? `aria-errormessage="${errorId}" aria-invalid="true"` : ""}
          >
          ${config.helperText ? `<p class="field-help" id="${helperId}">${config.helperText}</p>` : ""}
          ${error ? `<p class="field-error" id="${errorId}">${error}</p>` : ""}
        </div>
      `;
    }

    function SupportContactForm() {
      const alertMarkup = state.submitError
        ? `<div class="alert-message">${state.submitError}</div>`
        : "";

      return `
        <form id="support-form" novalidate>
          ${alertMarkup}
          ${FormField("fullName")}
          ${FormField("email")}
          ${FormField("phone")}
          <div class="form-actions">
            <button type="submit">Send message</button>
            <div class="status-message" role="status">${state.statusMessage}</div>
          </div>
        </form>
      `;
    }

    function SupportPage() {
      return `
        <main id="maincontent" tabindex="-1" class="page-shell">
          <section class="support-card" aria-labelledby="support-title">
            <p class="eyebrow">Support team</p>
            <h1 id="support-title">Get in touch with support</h1>
            <p class="intro">Share your contact details and our team will follow up as soon as possible.</p>
            <p class="required-note"><span class="required-mark" aria-hidden="true">*</span> Required fields</p>
            ${SupportContactForm()}
          </section>
        </main>
      `;
    }

    function App() {
      return SupportPage();
    }

    function render() {
      document.getElementById("root").innerHTML = App();

      const form = document.getElementById("support-form");
      const inputs = form.querySelectorAll("input");

      inputs.forEach((input) => {
        input.addEventListener("input", handleInput);
        input.addEventListener("blur", handleBlur);
      });

      form.addEventListener("submit", handleSubmit);
    }

    function handleInput(event) {
      const fieldName = event.target.name;
      const previousError = state.errors[fieldName] || "";
      state.values[fieldName] = event.target.value;
      let shouldRender = false;

      if (state.touched[fieldName]) {
        const nextError = validateField(fieldName, state.values[fieldName]);
        if (nextError) {
          state.errors[fieldName] = nextError;
        } else {
          delete state.errors[fieldName];
        }

        if (nextError !== previousError) {
          shouldRender = true;
        }
      }

      if (state.submitError) {
        state.submitError = "";
        shouldRender = true;
      }

      if (state.statusMessage) {
        state.statusMessage = "";
        shouldRender = true;
      }

      if (shouldRender) {
        render();
        const refreshedInput = document.getElementById(event.target.id);
        if (refreshedInput) {
          refreshedInput.focus();
        }
      }
    }

    function handleBlur(event) {
      const fieldName = event.target.name;
      const previousError = state.errors[fieldName] || "";
      state.touched[fieldName] = true;
      const nextError = validateField(fieldName, state.values[fieldName]);

      if (nextError) {
        state.errors[fieldName] = nextError;
      } else {
        delete state.errors[fieldName];
      }

      if (nextError !== previousError) {
        render();
      }
    }

    function focusFirstInvalidField(errors) {
      const firstInvalidField = FIELD_ORDER.find((fieldName) => errors[fieldName]);

      if (!firstInvalidField) {
        return;
      }

      const fieldId = getFieldConfig(firstInvalidField).id;
      const input = document.getElementById(fieldId);
      if (input) {
        input.focus();
      }
    }

    function handleSubmit(event) {
      event.preventDefault();
      FIELD_ORDER.forEach((fieldName) => {
        state.touched[fieldName] = true;
      });

      state.errors = validateAll(state.values);
      state.statusMessage = "";

      if (Object.keys(state.errors).length > 0) {
        state.submitError = "Please review the highlighted fields and correct the errors before sending.";
        render();
        focusFirstInvalidField(state.errors);
        return;
      }

      state.submitError = "";
      state.statusMessage = "Your support request is ready to send.";
      render();
    }

    render();
  </script>
</body>
