452.     function handleInput(event) {
453.       const fieldName = event.target.name;
454.       const previousError = state.errors[fieldName] || "";
455.       state.values[fieldName] = event.target.value;
456.       let shouldRender = false;
457. 
458.       if (state.touched[fieldName]) {
459.         const nextError = validateField(fieldName, state.values[fieldName]);
460.         if (nextError) {
461.           state.errors[fieldName] = nextError;
462.         } else {
463.           delete state.errors[fieldName];
464.         }
465. 
466.         if (nextError !== previousError) {
467.           shouldRender = true;
468.         }
469.       }
470. 
471.       if (state.submitError) {
472.         state.submitError = "";
473.         shouldRender = true;
474.       }
475. 
